const raw = $('Execute Workflow Trigger').first().json;
const q = (raw.query && typeof raw.query === 'object') ? raw.query : raw;
const slugify = s => s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'') || 'site';
const name = q.name || 'My Site';
const slug = (q.slug ? slugify(q.slug) : slugify(name));
const tools = String(q.tools||'').split('\n').map(s=>s.trim()).filter(Boolean).map(line=>{
  const p = line.split('|').map(x=>x.trim());
  return { name: p[0]||p[1]||'Tool', slug: slugify(p[1]||p[0]||'tool'), desc: p[2]||'', icon:'⚙️', keywords:[] };
});
let style = String(q.style||'').toLowerCase().trim();
if (!style) {
  const aud = String(q.audience||'').toLowerCase(); const mon = String(q.monetization||'ads');
  if (/child|kid|儿童|玩|fun|game/.test(aud)) style='playful';
  else if (/financ|crypto|投资|money|bank/.test(aud)) style='midnight';
  else if (/creativ|design|艺术|portfolio/.test(aud)) style='bold';
  else if (/saas|professional|企业|business|团队/.test(aud)) style='glassmorphism';
  else style='minimal';
}
const themeMap={minimal:'indigo',bold:'sunset',playful:'emerald',glassmorphism:'ocean',midnight:'midnight'};
const spec={ name:q.name||name, slug, domain:q.domain||'', tagline:q.tagline||'', lang:q.language||'en',
  audience:String(q.audience||'').split(',').map(s=>s.trim()).filter(Boolean),
  keywords:String(q.keywords||'').split(',').map(s=>s.trim()).filter(Boolean),
  tools, monetization:{model:q.monetization||'ads',currency:q.currency||'USD'},
  legal:{email:'',jurisdiction:'global'}, deploy:{target:'none'} };
const outDir = 'C:/Users/nathon.wang/WorkBuddy/2026-10-26-00-00-50/n8n-indie-builder/sites/' + slug;
const agentWorkDir = '/home/node/sites/' + slug;
const brief = [
  '# 站点实现简报 (AGENTS.md)','',
  '站点名称: ' + (q.name||name),
  '一句话定位: ' + (q.tagline||'(未填)'),
  '语言: ' + (q.language||'en'),
  '目标用户: ' + (q.audience||'(未填)'),
  '关键词(SEO): ' + (q.keywords||''),
  '视觉风格: ' + style,
  '变现模式: ' + (q.monetization||'ads'),'',
  '## 任务','1. 阅读 src/pages 下的占位工具页（标记“当前是占位实现”的页面）。',
  '2. 为每个工具实现**纯前端、可运行**的交互逻辑：不请求任何外部网络、不上传用户数据。',
  '3. 如需数据，使用浏览器端计算（如字符串处理、本地加解密、随机生成等）。',
  '4. 保证 SEO（语义化标签、meta、结构化数据）、响应式、可访问性。',
  '5. 不要改动工程骨架与构建配置，只补全工具页逻辑。','','## 工具清单'
].concat(tools.map(t => '- ' + t.name + (t.desc? '：'+t.desc : ''))).join('\n')
 + (q.agentExtra ? '\n\n## 用户额外指令\n' + q.agentExtra : '');
return [{ json: { spec, outDir, agentWorkDir, slug, style, brief,
  agentProvider: q.agentProvider||'claude', agentModel: q.agentModel||'', modelBaseUrl: q.modelBaseUrl||'', agentExtra: q.agentExtra||'' } }];

const q = $('Execute Workflow Trigger').first().json;
const b = $('Code: Build Spec').first().json;
const provider = String(b.agentProvider || 'claude').toLowerCase();
const wd = b.agentWorkDir;
const model = String(b.agentModel || '').trim();
const baseUrl = String(b.modelBaseUrl || '').trim();
const prompt = 'Read AGENTS.md in the current directory and implement every tool and page it describes. Produce production-quality Astro + TypeScript. Keep ALL logic client-side only: no external network requests, no data upload. Make the site SEO-friendly and responsive. After editing, if package.json has a build or check script, run it to verify. Summarize what you changed.';
let cmd;
if (provider === 'codex') {
  cmd = "codex exec '" + prompt + "' -s workspace-write -a never -m " + (model || 'gpt-5-codex');
} else if (provider === 'opencode') {
  cmd = "opencode run '" + prompt + "' --dir " + wd + ' --auto --format json' + (model ? ' -m ' + model : '');
} else {
  cmd = "claude -p '" + prompt + "' --allowedTools 'Edit,Write,Read,Bash,Grep,Glob,MultiEdit' --dangerously-skip-permissions --model " + (model || 'sonnet') + ' --output-format text';
}
const agentEnv = {};
if (baseUrl) {
  if (provider === 'claude') agentEnv.ANTHROPIC_BASE_URL = baseUrl;
  else { agentEnv.OPENAI_BASE_URL = baseUrl; agentEnv.ANTHROPIC_BASE_URL = baseUrl; }
}
return [{ json: { agentCommand: cmd, provider, agentWorkDir: wd, agentEnv } }];

const b = $('Code: Build Spec').first().json;
const gen = $('HTTP: /generate').first().json;
const cli = $('HTTP: Agent Run').all();
const br = $('HTTP: /complete (bridge)').all();
let agentOut = cli.length ? (cli[0].json.stdout||'') : (br.length ? JSON.stringify(br[0].json.report||'') : '');
const snippet = (typeof agentOut === 'string' ? agentOut : JSON.stringify(agentOut)).slice(0, 1200);
const ok = gen && gen.ok;
return [{ json: {
  result: (ok ? '✅ 站点「' + b.slug + '」已生成完成（风格 ' + b.style + '，提供方 ' + b.agentProvider + '）。' : '⚠️ 脚手架生成失败。')
    + '\n宿主目录: ' + b.outDir + '\n容器内目录: ' + b.agentWorkDir
    + '\n\nAgent 日志片段:\n' + snippet
} }];
